INSERT INTO cursos (slug, nombre, area, descripcion, precio, precio_regular, modalidad, nivel, semanas, lecciones, rating, inscritos, tag, imagen_url) VALUES ('analisis-a-la-musica-eclesiastica','Análisis a la Música Eclesiástica','Ministerio','El curso de ANÁLISIS A LA MÚSICA ECLESIASTICA, no es un curso de teoría musical o historia de la música. Es un curso de reflexión y análisis bíblico, teológico, pedagógico y psicológico, a cerca de la música que escuchas o ejecutas, en tu vida personal y ministerial. Se hace énfasis no solo en el texto, sino en todo el mensaje y contenido que se transmite a través de la música. Es un curso que puede ayudar a todo creyente y músico en su devoción y servicio de adoración a Dios.',30,40,'Virtual','Intermedio',4,11,4.9,17,'Intermedio','api/v1/covers/analisis-a-la-musica-eclesiastica.jpg') ON CONFLICT (slug) DO UPDATE SET nombre=EXCLUDED.nombre, area=EXCLUDED.area, descripcion=EXCLUDED.descripcion, nivel=EXCLUDED.nivel, semanas=EXCLUDED.semanas, lecciones=EXCLUDED.lecciones, inscritos=EXCLUDED.inscritos, tag=EXCLUDED.tag, imagen_url=EXCLUDED.imagen_url;
